from core import *

@register('differentiation','lorentzian-derivative-zero-window','complex-phase-derivative-zero-geometry','partial-fractions-and-phase-lattice','A high derivative has many real zeros. Complex poles turn its zero equation into a phase lattice, and strict interval endpoints require counting exactly which lattice points survive.','This is a real-zero localization problem, not evaluating one high derivative or applying a root count from parity.',[{'caseId':'order-'+str(n)+'-window-'+str(a)+'-'+str(b)+'-'+str(q),'order':n,'a':a,'b':b,'q':q,'purpose':'The derivative order and angular window change the number of interior phase-lattice points and endpoint exclusions.'} for n,a,b,q in [(9,1,2,7),(10,1,3,8),(11,2,4,9),(12,1,2,5),(13,2,5,11),(14,1,3,7),(15,2,3,8),(16,1,4,9),(17,3,5,12),(18,2,5,13),(19,1,3,10),(20,3,7,16)]],['complex partial fractions','polar form','strict integer counting'])
def lorentzian(case):
 m=case['order'];a=case['a'];b=case['b'];q=case['q'];low=R(a*(m+1),q);high=R(b*(m+1),q);inside=[j for j in range(1,m+1) if low<j<high];A=s.Integer(len(inside))
 P=s.Integer(1)
 for j in range(m):P=s.expand((1+x*x)*s.diff(P,x)-2*(j+1)*x*P)
 Z=s.expand((x+s.I)**(m+1)-(x-s.I)**(m+1))/(2*s.I);ck('The independently differentiated real numerator matches the complex-pole formula',P,(-1)**m*s.factorial(m)*Z)
 condition('Both angular endpoints are in the decreasing cotangent branch',0<R(a,q)<R(b,q)<1,'Cotangent is strictly decreasing on(0,pi). The mapped real interval reverses endpoint order.')
 ck('Integer-window count by floor and ceiling',A,max(0,s.ceiling(high)-s.floor(low)-1))
 analytic('Complete real zero parametrization',['For real x the poles plus/minus i never lie on the domain. The cotangent parametrization x=cot theta is bijective for0<theta<pi.'],['Differentiate the two partial fractions exactly. After combining denominators the derivative vanishes exactly when(x+i)^(m+1)-(x-i)^(m+1)=0.','For x=cot theta, x+i=e^(i theta)/sin theta and x-i=e^(-i theta)/sin theta. Hence the zero equation is sin((m+1)theta)=0.','The allowed phases are j*pi/(m+1), j=1..m, all distinct. Reverse the stated cotangent endpoints and count the strict rational inequalities; an integer at either endpoint is excluded.'])
 closed=sum(int(bool(low<=j<=high)) for j in range(1,m+1));left=sum(int(bool(low<=j<high)) for j in range(1,m+1));right=sum(int(bool(low<j<=high)) for j in range(1,m+1));wrongorder=sum(int(bool(R(a*m,q)<j<R(b*m,q))) for j in range(1,m));width=s.floor(high-low)
 pool=[(closed,'Include both boundary zeros'),(left,'Include the left phase boundary'),(right,'Include the right phase boundary'),(wrongorder,'Use the derivative order instead of the pole-power order'),(width,'Round only the interval length and discard its lattice phase'),(2*A,'Count conjugate pole representations as distinct real roots'),(m-A,'Count the complementary phase intervals'),(m,'Count every real derivative zero instead of the specified window')]
 return candidate(r'f(x)=\frac1{1+x^2}.'+T('How many distinct real zeros of ')+r'f^{('+str(m)+r')}(x)'+T(' lie in the open interval ')+r'\left(\cot\!\left('+L(R(b,q)*pi)+r'\right),\ \cot\!\left('+L(R(a,q)*pi)+r'\right)\right)?',A,pool,[r'f(x)=\frac1{2i}\left(\frac1{x-i}-\frac1{x+i}\right)',r'f^{('+str(m)+r')}(x)=\frac{(-1)^{'+str(m)+r'}'+str(m)+r'!}{2i}\left((x-i)^{-'+str(m+1)+r'}-(x+i)^{-'+str(m+1)+r'}\right)',r'x=\cot\theta,\quad0<\theta<\pi,\qquad f^{('+str(m)+r')}(x)=0\iff\sin('+str(m+1)+r'\theta)=0',r'\theta=\frac{j\pi}{'+str(m+1)+r'},\quad1\le j\le'+str(m)+r',\qquad '+L(low)+r'<j<'+L(high),r'j\in\{'+','.join(map(str,inside))+r'\}',T('The interval is open, so any lattice point exactly at a boundary is excluded.')],'high-derivative-real-zeros-strict-angular-window',answerForm='integer-count')

@register('differentiation','chebyshev-edge-derivative-correction','iterated-Chebyshev-boundary-layer','dynamical-conjugacy-and-two-scale-derivative-expansion','A repeated nonlinear composition has exponentially growing derivative. Trigonometric conjugacy reveals its moving endpoint layer, where a second-order angle correction survives after the leading term is removed.','The endpoint Markov value alone gives only the derivative at exactly one; this evaluates a moving interior point and a nonzero correction after cancellation.',[{'caseId':'phase-'+str(i),'phase':str(r),'purpose':'Distinct dimensionless phase positions include cancellation, opposite signs and nonzero leading terms.'} for i,r in enumerate([R(1,3),R(1,2),R(2,3),1,R(4,3),R(3,2),R(5,3),2,R(1,4),R(3,4),R(5,4),R(7,4)])],['composition identities','Taylor expansions with remainder','moving-point asymptotics'])
def chebyshev_edge(case):
 alpha=R(case['phase'])*pi;c=alpha**2/2;lead=s.sin(alpha)/alpha;first=alpha**2*s.cos(alpha)/24;second=alpha*s.sin(alpha)/8;A=s.expand(first+second);u=s.symbols('u',positive=True)
 theta=alpha*u+alpha**3*u**3/24
 ck('The approximate inverse cosine has the required fourth-order cancellation',s.expand(s.series(s.cos(theta),u,0,6).removeO()).coeff(u,4),0)
 ck('The second-order scaled sine denominator',s.expand(s.series(s.sin(theta)/u,u,0,4).removeO()).coeff(u,2),-alpha**3/8)
 expansion=s.series(s.sin(alpha+alpha**3*u*u/24)/(alpha-alpha**3*u*u/8),u,0,4).removeO();ck('Independent series division gives the correction coefficient',s.expand(expansion).coeff(u,2),A)
 v=s.symbols('v',real=True);ck('The nonlinear recurrence doubles the angular coordinate',s.expand_trig(s.cos(2*v)),2*s.cos(v)**2-1)
 analytic('Endpoint layer with controlled remainder',['For each fixed positive phase, the evaluation point lies in(-1,1) for all sufficiently large n.','Taylor remainders are uniform in a fixed neighborhood of the limiting angle.'],['The recurrence gives P_n(cos theta)=cos(2^n theta) by induction. Differentiate to obtain P_n prime(cos theta)=2^n sin(2^n theta)/sin theta.','Put N=2^n and x=1-alpha^2/(2N^2). Inverting cosine near zero gives theta=alpha/N+alpha^3/(24N^3)+O(N^-5).','Expand both numerator and denominator: N theta=alpha+alpha^3/(24N^2)+O(N^-4), and N sin theta=alpha-alpha^3/(8N^2)+O(N^-4).','Divide these two expansions, subtract sin(alpha)/alpha, and multiply by N squared. The nonzero denominator alpha justifies the division and the remainder tends to zero.'])
 pool=[(first,'Retain the angular correction but discard the sine-denominator correction'),(second,'Replace inverse cosine by its leading square-root term'),(first-second,'Reverse the sign of the sine-denominator correction'),(-first+second,'Reverse the inverse-cosine correction'),(3*first+second,'Use the inverse-sine cubic coefficient in place of inverse cosine near one'),(first+2*second,'Double-count the denominator correction'),(2*first+second,'Double-count the angular correction'),(first+R(4,3)*second,'Keep the sine cubic denominator term but omit the angle correction inside that denominator'),(first+R(5,3)*second,'Add rather than subtract the inverse-cosine correction inside the sine denominator'),(-A,'Reverse the subtraction of the leading term')]
 return candidate(r'P_0(x)=x,\qquad P_{n+1}(x)=2P_n(x)^2-1.'+T('Determine ')+r'\lim_{n\to\infty}4^n\left[4^{-n}P_n\prime\left(1-\left('+L(c)+r'\right)4^{-n}\right)-'+L(lead)+r'\right].',A,pool,[r'P_n(\cos\theta)=\cos(2^n\theta),\qquad P_n\prime(\cos\theta)=\frac{2^n\sin(2^n\theta)}{\sin\theta}',r'N=2^n,\quad\alpha='+L(alpha)+r',\quad\theta_N=\arccos\left(1-\frac{\alpha^2}{2N^2}\right)=\frac\alpha N+\frac{\alpha^3}{24N^3}+O(N^{-5})',r'N\sin\theta_N=\alpha-\frac{\alpha^3}{8N^2}+O(N^{-4}),\qquad\sin(N\theta_N)=\sin\alpha+\frac{\alpha^3\cos\alpha}{24N^2}+O(N^{-4})',r'\frac{P_n\prime(1-\alpha^2/(2N^2))}{N^2}=\frac{\sin\alpha}{\alpha}+\frac1{N^2}\left(\frac{\alpha^2\cos\alpha}{24}+\frac{\alpha\sin\alpha}{8}\right)+O(N^{-4})',T('The evaluation points are interior for all sufficiently large indices. Substitute the displayed phase after taking the correction term.'),L(A)],'nonlinear-composition-endpoint-layer-derivative-second-correction')

@register('differentiation','singular-reparametrized-wronskian','Wronskian-reparametrization-triangularity','derivative-basis-triangularization-and-vanishing-order','A determinant contains many cancelling derivative terms. Reparametrization makes the derivative transformation triangular; its diagonal determines the entire vanishing order at a singular coordinate.','This differs from the moment-Hankel identity: the determinant is a Wronskian under a singular change of variable, not an integral Gram determinant.',[{'caseId':'dimension-'+str(r)+'-contact-'+str(h),'r':r,'h':h,'purpose':'Matrix dimension and contact order both change, beyond amplitude or coordinate rescaling.'} for r,h in [(3,2),(3,3),(3,4),(3,5),(4,2),(4,3),(4,4),(4,5),(5,2),(5,3),(6,2),(6,3)]],['Wronskians','higher chain rule','triangular matrices','order of a zero'])
def wronskian(case):
 r=case['r'];h=case['h'];g=x**h+x**(h+1);lam=s.symbols('lambda');d=r*(r-1)//2;A=s.Integer((h-1)*d);B=[s.Integer(1)]
 for j in range(1,r):B.append(s.expand(s.diff(B[-1],x)+lam*s.diff(g,x)*B[-1]))
 C=s.Matrix(r,r,lambda i,j:s.expand(B[i]).coeff(lam,j));ck('Derivative-polynomial coefficient matrix is triangular with the chain-rule diagonal',C.det(),s.diff(g,x)**d)
 V=s.Matrix(r,r,lambda i,j:s.Integer(j+1)**i);vand=s.prod(j-i for i in range(1,r+1) for j in range(i+1,r+1));ck('The remaining exponential derivative matrix is a Vandermonde',V.det(),vand)
 lead=s.Integer(h)**d*vand;ck('Leading coefficient after extracting the claimed zero order',s.limit(s.diff(g,x)**d*V.det()/x**A,x,0),lead);condition('The leading coefficient is nonzero',lead>0,'No hidden cancellation can increase the vanishing order.')
 analytic('Wronskian change of variable',['The exponentials and polynomial coordinate map are real analytic. Distinct integer exponential rates are explicit.'],['Writing differentiation in x as g prime times differentiation in g, every derivative of order i is(g prime)^i times the ith g-derivative plus lower g-derivatives.','The triangular row transformation has determinant(g prime)^(0+1+...+r-1). The Wronskian of the exponential functions in g is exp(sum rates times g) times their nonzero Vandermonde.','The exponential factor never vanishes. The coordinate derivative has a zero of exactly order h-1 at zero, so the determinant order is(h-1)r(r-1)/2.'])
 return candidate(r'g(x)='+L(g)+r',\qquad f_j(x)=e^{jg(x)}\ (1\le j\le'+str(r)+r'),\qquad W(x)=\det\big(f_j^{(i)}(x)\big)_{\substack{0\le i\le'+str(r-1)+r'\\1\le j\le'+str(r)+r'}}.'+T('Find the order of the zero of W at the origin; this is the smallest nonnegative integer k for which ')+r'W^{(k)}(0)\ne0.',A,[(r*(h-1),'Count one coordinate derivative per column rather than per derivative order'),((h-1)*r*(r+1)//2,'Start the row derivative orders at one'),(h*d,'Use the order of g instead of the order of its derivative'),((h-1)*(r-1)*(r-2)//2,'Delete the highest derivative row before counting'),(d,'Ignore the higher-order zero of the coordinate derivative'),((h-1)*(r-1),'Keep only the highest derivative row in the triangular diagonal product'),(0,'Assume independent analytic functions have a Wronskian nonzero at every point'),(2*A,'Square the determinant transformation as if it were a Gram matrix')],[r'\frac{\mathrm d^i}{\mathrm dx^i}=(g\prime)^i\frac{\mathrm d^i}{\mathrm dg^i}+\sum_{k<i}c_{ik}(x)\frac{\mathrm d^k}{\mathrm dg^k}',T('This is a triangular transformation of the derivative rows. Its diagonal product is the power shown below.'),r'W(x)=g\prime(x)^{'+str(d)+r'}e^{'+str(r*(r+1)//2)+r'g(x)}\prod_{1\le i<j\le'+str(r)+r'}(j-i)',r'g\prime(x)='+L(s.diff(g,x))+r',\qquad\operatorname{ord}_0(g\prime)='+str(h-1),T('The exponential and Vandermonde factors are nonzero at zero, so they cannot cancel the leading term.'),r'\operatorname{ord}_0W='+str(h-1)+r'\cdot'+str(d)+r'='+L(A)],'singular-coordinate-Wronskian-exact-vanishing-order',answerForm='integer-order')

@register('differentiation','hermite-inverse-gap-moment','orthogonal-polynomial-root-inverse-gap-identities','differentiate-ODE-at-roots-and-Newton-moment-trace','A symmetric inverse-gap sum is recovered without solving for roots. Local differentiated differential-equation identities supply each gap sum; global polynomial moments then close the calculation.','The Hermite discriminant uses resultants and a product of all gaps. This asks weighted inverse-square gap sums and requires a different local root identity; the broader orthogonal-polynomial connection is disclosed.',[{'caseId':'degree-'+str(n)+'-weight-'+str(q),'n':n,'q':q,'purpose':'Polynomial degree and weighted root moment vary; no coordinate-scaled copies.'} for n,q in [(6,1),(7,1),(8,1),(9,1),(6,2),(7,2),(8,2),(9,2),(8,3),(9,3),(10,3),(11,3)]],['polynomial differential equations','logarithmic derivatives at simple roots','Newton sums','complex polynomial roots'])
def hermite_gaps(case):
 N=case['n'];q=case['q'];P=sum((-1)**j*s.factorial(N)*x**(N-2*j)/(s.factorial(j)*s.factorial(N-2*j)*4**j) for j in range(N//2+1));P=s.expand(P)
 ck('Explicit coefficient construction satisfies the required polynomial ODE',s.diff(P,x,2)-2*x*s.diff(P,x)+2*N*P,0)
 condition('The polynomial has no repeated complex root',s.gcd(P,s.diff(P,x))==1,'This is independently computed; the differential equation also excludes a common zero by uniqueness.')
 # Matrix trace independently sums any polynomial over all complex roots.
 coeff=s.Poly(P,x).all_coeffs();C=s.zeros(N)
 for j in range(N-1):C[j+1,j]=1
 for j in range(N):C[j,N-1]=-coeff[N-j]
 def moment(power):return s.trace(C**power)
 A=s.factor((2*(N-1)*moment(2*q)-moment(2*q+2))/3)
 inv=s.invert(s.diff(P,x),P,x);S2=s.rem((s.diff(P,x,2)*inv/2)**2-s.diff(P,x,3)*inv/3,P,x);ck('Rootwise inverse-gap identity checked in the quotient polynomial ring',s.rem(S2-(2*(N-1)-x*x)/3,P,x),0)
 Q=s.rem(x**(2*q)*S2,P,x);oracle=sum(v*moment(int(mon[0])) for mon,v in s.Poly(Q,x).terms());ck('Independent rational-function root trace matches the weighted answer',oracle,A)
 analytic('Rootwise gap identity',['The monic polynomial is explicitly defined by its degree and differential equation. It has simple complex roots; no root approximation is used.'],['Write P(x)=(x-r)Q(x) at a simple root. Then P second/(2P prime)=sum over other roots1/(r-s), and P third/(3P prime) is the square of that sum minus the sum of inverse squared gaps.','The ODE at r gives the first sum r. Differentiating the ODE once gives P third/P prime=4r^2-2(N-1). Consequently each inverse-square gap sum is[2(N-1)-r^2]/3.','Multiply by r^(2q) and sum over roots. Each unordered pair contributes exactly the displayed symmetric numerator. The required polynomial moments follow from Newton sums or companion-matrix traces.'])
 M=moment(2*q);K=moment(2*q+2)
 return candidate(T('Let P be the unique monic polynomial of degree ')+str(N)+T(' satisfying ')+r'P^{\prime\prime}(x)-2xP\prime(x)+'+str(2*N)+r'P(x)=0.'+T('Let its distinct complex roots be ')+r'r_1,\ldots,r_{'+str(N)+r'}.'+T('Evaluate ')+r'\sum_{1\le i<j\le'+str(N)+r'}\frac{r_i^{'+str(2*q)+r'}+r_j^{'+str(2*q)+r'}}{(r_i-r_j)^2}.',A,[(2*A,'Count each unordered pair twice after summing the rootwise identity'),(A/2,'Divide again although the symmetric numerator already accounts for both endpoints'),((2*(N-1)*M+K)/3,'Reverse the negative squared-root term'),((2*N*M-K)/3,'Forget the derivative of the coefficient multiplying P prime'),((2*(N-1)*M-K)/2,'Use a second-derivative denominator in the third-derivative root identity'),((2*(N-1)*M-2*K)/3,'Count the squared first logarithmic-derivative term twice')],[r'\frac{P^{\prime\prime}(r_i)}{2P\prime(r_i)}=\sum_{j\ne i}\frac1{r_i-r_j}=r_i',r'\frac{P^{\prime\prime\prime}(r_i)}{3P\prime(r_i)}=\left(\sum_{j\ne i}\frac1{r_i-r_j}\right)^2-\sum_{j\ne i}\frac1{(r_i-r_j)^2}',T('Differentiate the supplied differential equation once and substitute a root.'),r'\frac{P^{\prime\prime\prime}(r_i)}{P\prime(r_i)}=4r_i^2-'+str(2*(N-1)),r'\sum_{j\ne i}\frac1{(r_i-r_j)^2}=\frac{'+str(2*(N-1))+r'-r_i^2}{3}',r'P(x)='+L(P),r'\sum_i r_i^{'+str(2*q)+r'}='+L(M)+r',\qquad\sum_i r_i^{'+str(2*q+2)+r'}='+L(K),T('These two power sums follow by coefficient comparison in the logarithmic derivative of the displayed monic polynomial. Summing the rootwise identities counts each symmetric unordered-pair numerator once.'),r'\frac{'+str(2*(N-1))+r'\cdot('+L(M)+r')-('+L(K)+r')}{3}='+L(A)],'orthogonal-polynomial-weighted-inverse-square-gap-moment')

@register('differentiation','cosine-equation-regularity','functional-equation-regularity-bootstrap','integrated-functional-equation-and-ODE-classification','Continuity alone must be upgraded to differentiability before the equation can be differentiated. A local averaging identity provides the bootstrap and then an ODE determines the derivative.','This is a global functional equation with no initial differentiability assumption; it is not substitution into a supplied differential equation.',[{'caseId':'normalized-hyperbolic-branch','purpose':'One normalized functional-equation problem; scalar/time changes are deliberately not counted as extra advanced capacity.'}],['continuous functional equations','fundamental theorem of calculus','linear ODE uniqueness'])
def cosine_equation(case):
 A=s.log(2)**2;w=s.cosh(s.log(2)*x);ck('The proposed branch has the prescribed unit value',w.subs(x,1),R(5,4));ck('The proposed derivative constant',s.diff(w,x,2).subs(x,0),A)
 ck('The hyperbolic addition identity verifies the functional equation',s.expand_trig(s.cosh(s.log(2)*(x+y))+s.cosh(s.log(2)*(x-y))-2*w*s.cosh(s.log(2)*y)),0)
 analytic('Continuity-to-smoothness bootstrap',['The real function is continuous on the whole real line, satisfies the displayed equation for every real pair, and f(0)=1.'],['Choose a small positive h with integral0h f nonzero, which continuity and f0=1 guarantee. Integrating the functional equation in y gives2f(x) integral0h f=integral(x-h)^(x+h) f.','The right side is continuously differentiable. Thus f is C1; iterating this identity gives smoothness. Substitution x=0 shows f is even, so f prime0=0.','Differentiate the equation twice with respect to y at0 to obtain f second(x)=f second0 times f(x). If the constant is nonpositive, the unit value cannot exceed1; hence it is positive and f(x)=cosh(sqrt(c)x).','The unit value5/4 forces exp(sqrt(c))=2, because the positive reciprocal root is selected. Therefore c=(ln2)^2.'])
 return candidate(T('A continuous real function f on the real line satisfies ')+r'f(x+y)+f(x-y)=2f(x)f(y)\quad(x,y\in\mathbb R),\qquad f(0)=1,\quad f(1)=\frac54.'+T('The hypotheses force a second derivative at the origin. Find ')+r'f^{\prime\prime}(0).',A,[(s.log(2),'Return the positive ODE frequency rather than its square'),(s.log(2)**2/2,'Retain the half from one side of the symmetric equation'),(2*s.log(2)**2,'Count both symmetric terms without dividing by two'),(s.log(R(5,4))**2,'Replace the hyperbolic cosine value by an exponential value'),(-s.log(2)**2,'Select the oscillatory instead of the hyperbolic branch')],[T('Continuity at zero makes the following denominator nonzero for a sufficiently small positive h.'),r'f(x)=\frac{\displaystyle\int_{x-h}^{x+h}f(t)\,\mathrm dt}{\displaystyle2\int_0^hf(t)\,\mathrm dt}',T('The right side gains one continuous derivative. Repeating proves smoothness; the original equation also makes f even.'),r'f\prime(0)=0,\qquad f^{\prime\prime}(x)=c f(x),\quad c=f^{\prime\prime}(0)',T('A nonpositive c gives a constant or cosine branch with unit value at most one. The prescribed larger value selects the positive branch.'),r'f(x)=\cosh(\sqrt c\,x),\qquad\frac{e^{\sqrt c}+e^{-\sqrt c}}2=\frac54',r'e^{\sqrt c}=2,\qquad c=(\ln2)^2'],'continuous-cosine-equation-smoothing-and-branch-selection')

@register('differentiation','commuting-parabolic-jet','parabolic-composition-centralizer-jets','commutation-resonance-and-truncated-composition','An analytic function is not given explicitly, only by commuting with a tangent-to-identity map and two derivatives. Resonance cancels the apparent highest unknown; the next coefficient recursively forces the requested jet.','Direct inverse-series coefficient matching solves a supplied identity. This is a centralizer condition with a free quadratic coefficient, higher-order resonances and an existence witness.',[{'caseId':'jet-'+str(i),'b':b,'c':c,'r':r,'order':m,'purpose':'Different nonlinear maps, commuting time and jet order, with explicit analytic iterate witnesses.'} for i,(b,c,r,m) in enumerate([(1,1,2,4),(2,-1,3,4),(-1,2,2,5),(0,1,3,5),(1,-1,2,6),(2,1,3,6),(-2,1,2,7),(1,2,3,7),(3,-1,4,5),(-1,3,4,6),(2,2,4,7),(0,-1,5,6)])],['analytic composition','Taylor jets','coefficient resonance','existence by iteration'])
def commuting(case):
 b=case['b'];c=case['c'];r=case['r'];m=case['order'];F=x+x*x+b*x**3+c*x**4
 trunc=lambda P,N:s.Poly(s.expand(P),x).truncate(N) if False else s.Poly(s.expand(P),x)
 def cut(P,N):return s.Add(*[coef*x**mon[0] for mon,coef in s.Poly(s.expand(P),x).terms() if mon[0]<N])
 def compose(P,Q,N):
  out=0;power=1
  for j in range(s.degree(P,x)+1):
   out+=s.expand(P).coeff(x,j)*power;power=cut(power*Q,N)
  return cut(out,N)
 H=x+r*x*x;values={2:s.Integer(r)};equations=[]
 for j in range(3,m+1):
  v=s.Symbol('v');J=H+v*x**j;eq=s.expand(compose(F,J,j+2)-compose(J,F,j+2)).coeff(x,j+1);slope=s.diff(eq,v);condition('Nonzero resonance coefficient at degree '+str(j+1),slope!=0,'The first free quadratic coefficient is fixed, and every higher coefficient is uniquely determined.')
  value=s.solve(eq,v)[0];ck('The independently formed commutation coefficient vanishes',eq.subs(v,value),0);H+=value*x**j;values[j]=value;equations.append((j,eq,value))
 witness=x;previous=x
 for j in range(r):previous=witness;witness=compose(F,witness,m+1)
 ck('The analytic iterate witness has every forced Taylor coefficient',H,witness)
 A=s.factorial(m)*values[m];flow=s.factorial(m)*r**(m-1);prev=s.factorial(m)*s.expand(previous).coeff(x,m)
 analytic('Jet uniqueness with an analytic witness',['The unknown function is real analytic near zero, fixes zero, is tangent to the identity, and commutes wherever both compositions are defined.'],['Expand G=x+r x^2+g3 x^3+... . In F composed with G minus G composed with F, the coefficient involving the next unused derivative cancels because both maps have linear coefficient1.','At degree j+1, the new coefficient g_j occurs linearly with nonzero factor proportional to j-2; lower coefficients are already known. Thus the stated quadratic coefficient recursively fixes each higher jet.','The r-fold composition of F is analytic, commutes with F and has quadratic coefficient r. It supplies an existence witness, so the recursively determined jet is not merely formal.'])
 return candidate(r'F(x)='+L(F)+r'.'+T('Let G be real analytic near zero and satisfy ')+r'G(0)=0,\quad G\prime(0)=1,\quad G^{\prime\prime}(0)='+str(2*r)+r',\quad F(G(x))=G(F(x))'+T(' for all sufficiently small real x. Find ')+r'G^{('+str(m)+r')}(0).',A,[(values[m],'Return the Taylor coefficient without its factorial'),(flow,'Replace the actual map by the quadratic Riccati time flow'),(prev,'Use one fewer composition in the analytic witness'),(A*m,'Multiply by the factorial ratio one extra time'),(A/m,'Omit the final factor in the derivative factorial'),(s.factorial(m)*values[m-1],'Use the preceding jet coefficient')],[r'G(x)=x+'+str(r)+r'x^2+\sum_{j=3}^{'+str(m)+r'}g_jx^j+O(x^{'+str(m+1)+r'})',T('Compare successive coefficients in the commutation identity. The next unlisted Taylor coefficient cancels at each step; the coefficient currently being solved has a nonzero linear multiplier.'),*[(r'[x^{'+str(j+1)+r'}](F\circ G-G\circ F)='+L(eq).replace('v','g_{'+str(j)+'}')+r'=0\quad\Longrightarrow\quad g_{'+str(j)+r'}='+L(v)) for j,eq,v in equations],T('Existence is supplied by the stated positive-integer number of compositions of F with itself. That iterate commutes with F and has precisely the required quadratic coefficient.'),r'G^{('+str(m)+r')}(0)='+str(m)+r'!\,g_{'+str(m)+r'}='+L(A)],'analytic-parabolic-centralizer-forced-resonant-jet')
